(()=>{let attempts=0;const status=document.createElement('div');status.setAttribute('role','status');status.className='note';status.textContent='Connecting to planetary command…';document.getElementById('page-overview')?.prepend(status);function load(){attempts++;const script=document.createElement('script');script.src='/game-runtime.js?v=0.117.0'+(attempts>1?'&retry='+attempts:'');script.onload=()=>{if(window.starfallGameReady)status.remove();else{status.textContent='Command could not initialise. Open the error log for details.';const button=document.createElement('button');button.className='btn';button.textContent='RELOAD COMMAND';button.onclick=()=>location.reload();status.append(button);}};script.onerror=()=>{script.remove();if(attempts<3){status.textContent='Reconnecting to planetary command…';setTimeout(load,500*attempts);}else{status.textContent='Command files could not load. Your saved round has been retained.';const button=document.createElement('button');button.className='btn';button.textContent='RETRY CONNECTION';button.onclick=()=>{attempts=0;status.replaceChildren();load();};status.append(button);}};document.body.append(script);}load();})();
